<template><ion-page><ion-header class="ion-no-border"><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/app/more" /></ion-buttons><ion-title>Security</ion-title></ion-toolbar></ion-header><ion-content><main class="page-wrap"><StatePanel v-if="loading" loading title="Loading security events" message="Retrieving recent detections." /><StatePanel v-else-if="error" tone="danger" title="Security events unavailable" :message="error" :retry="load" /><section v-else class="security-list"><article v-for="item in events" :key="item.id"><div class="security-thumb"><ion-icon :icon="personOutline" /></div><div><span>{{ item.detection_type_display }}</span><h2>{{ item.source_display }}</h2><p>{{ Math.round(item.confidence * 100) }}% confidence · {{ item.status_display }}</p><small>{{ new Date(item.detected_at).toLocaleString() }}</small></div></article><StatePanel v-if="!events.length" title="No security detections" message="Recent detection history is clear." /></section></main></ion-content></ion-page></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { IonBackButton, IonButtons, IonContent, IonHeader, IonIcon, IonPage, IonTitle, IonToolbar } from '@ionic/vue'; import { personOutline } from 'ionicons/icons'; import StatePanel from '@/components/StatePanel.vue'; import { securityService, type Detection } from '@/services/security.service';
const events = ref<Detection[]>([]); const loading = ref(true); const error = ref(''); async function load() { loading.value = true; error.value = ''; try { events.value = (await securityService.list()).results; } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load security events.'; } finally { loading.value = false; } } onMounted(load);
</script>
